(()=>{const cloud=document.getElementById('bubble-cloud'),dialog=document.getElementById('story-dialog');const e=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};let returnFocus=null;
const positions=[[3,15,165],[33,3,205],[72,12,172],[13,55,188],[48,57,153],[77,57,183]];
async function init(){const response=await fetch('/portfolio/collections.json');if(!response.ok)throw Error();const collections=await response.json();const r=await fetch('https://zah-public-editor.zahmediaofficial.workers.dev/api/testimonials');if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data.reviews))throw Error();const stories=data.reviews;
if(!stories.length){cloud.classList.add('empty');cloud.append(e('h2','Your story could be the first.'),e('p','Have we captured a moment together? Share your experience below.'));document.querySelector('.bubble-section-top>span:last-child').hidden=true;document.querySelector('.bubble-help').hidden=true;return;}
if(stories.length>6)cloud.classList.add("many");stories.forEach((r,i)=>{const g=collections.find(g=>g.slug===r.projectId);const cover=r.photo;const button=e('button');button.type='button';button.className='story-bubble';const [x,y,size]=positions[i%positions.length];button.style.cssText=`--x:${x}%;--y:${y}%;--size:${size}px;--speed:${5+i*.7}s;--delay:-${i*1.4}s`;button.setAttribute('aria-label',`${r.demo?'Preview story':'Read testimonial'}: ${r.name}`);button.setAttribute('aria-haspopup','dialog');const portrait=e('span');portrait.className='bubble-portrait';if(cover){const image=e('img');image.src=cover.src.startsWith('https:')?cover.src:'/portfolio/'+cover.src;image.alt='';portrait.append(image);}else portrait.append(e('span',r.name.slice(0,1)));const label=e('span',r.name);label.className='bubble-label';const project=e('span',r.demo?'Sample story':r.project);project.className='bubble-project';const mark=e('span','“');mark.className='bubble-mark';mark.setAttribute('aria-hidden','true');button.append(portrait,label,project,mark);button.addEventListener('click',()=>open(r,g,button));cloud.append(button);});}
function open(r,g,button){returnFocus=button;const rect=button.getBoundingClientRect();dialog.style.setProperty('--launch-x',(rect.left+rect.width/2-innerWidth/2)*.45+'px');dialog.style.setProperty('--launch-y',(rect.top+rect.height/2-innerHeight/2)*.45+'px');document.getElementById('story-demo').textContent=r.demo?'DESIGN SAMPLE · NOT A REAL CLIENT TESTIMONIAL':'';document.getElementById('story-category').textContent=r.project||'Photography experience';document.getElementById('story-title').textContent=r.heading||'In their words.';document.getElementById('story-quote').textContent=r.text;document.getElementById('story-name').textContent=r.demo?'Client’s name would appear here':r.name;document.getElementById('story-handle').textContent=r.demo?'Optional social handle · plain text':r.handle||'';const photos=document.getElementById('story-photos');photos.replaceChildren();const pair=(g?.photos||[]).slice(0,2);for(const p of pair){const figure=e('figure'),img=e('img');img.src='/portfolio/'+p.src;img.alt=p.alt;img.width=p.width;img.height=p.height;figure.append(img);photos.append(figure);}const link=document.getElementById('story-gallery');link.href=g?'/'+g.path:'/portfolio/';dialog.showModal();document.body.style.overflow='hidden';}
document.getElementById('story-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',ev=>{const rect=dialog.getBoundingClientRect();if(ev.target===dialog&&(ev.clientX<rect.left||ev.clientX>rect.right||ev.clientY<rect.top||ev.clientY>rect.bottom))dialog.close();});dialog.addEventListener('close',()=>{document.body.style.overflow='';returnFocus?.focus();});init().catch(()=>{cloud.classList.add('empty');cloud.replaceChildren(e('p','Client stories couldn’t load just now. Please try again shortly.'));document.querySelector('.bubble-section-top>span:last-child').hidden=true;document.querySelector('.bubble-help').hidden=true;});})();
